package com.loja.checkout.dominio.entrega;

import com.loja.checkout.dominio.Pedido;
import java.math.BigDecimal;

/**
 * Uma opcao de entrega. Para adicionar uma transportadora nova basta criar
 * uma classe que implemente esta interface e anota-la com {@code @Component}.
 */
public interface ModalidadeEntrega {

    /** Codigo enviado pelo site, ex.: EXPRESSA. */
    String codigo();

    /** Prazo prometido, em dias. */
    int prazoDias();

    /** Frete cobrado para o pedido, em reais e centavos. */
    BigDecimal calcularFrete(Pedido pedido);

    /** Se a modalidade atende o pedido (ex.: motoboy tem limite de peso). */
    default boolean atende(Pedido pedido) {
        return true;
    }
}
EOF
cat > dominio/entrega/EntregaPorPeso.java <<'EOF'
package com.loja.checkout.dominio.entrega;

import com.loja.checkout.comum.Dinheiro;
import com.loja.checkout.dominio.Pedido;
import java.math.BigDecimal;

/** Base das modalidades que cobram uma taxa fixa mais um valor por kg do pedido. */
public abstract class EntregaPorPeso implements ModalidadeEntrega {

    private final BigDecimal taxaFixa;
    private final BigDecimal valorPorKg;

    protected EntregaPorPeso(String taxaFixa, String valorPorKg) {
        this.taxaFixa = new BigDecimal(taxaFixa);
        this.valorPorKg = new BigDecimal(valorPorKg);
    }

    @Override
    public BigDecimal calcularFrete(Pedido pedido) {
        return Dinheiro.centavos(taxaFixa.add(valorPorKg.multiply(pedido.pesoTotalKg())));
    }
}
EOF
